def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    templates = []
    singles = []

    # Horizontal nonzero runs are sequences; length-one runs are anchors.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            run = grid[r][start:c]
            if len(run) > 1:
                templates.append(run)
            else:
                singles.append((r, start, run[0]))

    for r, c, color in singles:
        for seq in templates:
            if color in seq:
                start = c - seq.index(color)
                for i, value in enumerate(seq):
                    cc = start + i
                    if 0 <= cc < w:
                        out[r][cc] = value
                break

    return out
